<section class="card"><h2>Leave requests</h2><p class="muted">Requests and review decisions are retained. Entitlement balances are not calculated until Tivoli’s leave policy is configured.</p><div class="scroll"><table><thead><tr><th>Type / dates</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($snapshot['leaves'] as $leave):?><tr><td><?=access_h($leave['type'] ?? $leave['leave_type'] ?? '')?><br><?=access_h(display_date($leave['start_date'] ?? ''))?> → <?=access_h(display_date($leave['end_date'] ?? ''))?></td><td class="hr-multiline"><?=access_h($leave['reason'] ?? '')?></td><td><?=access_h($leave['status'])?></td><td><?php if($leave['status']==='pending'&&$can('hr.approve')):?><form method="post"><?php hr_fields('review_leave',$id,$version);?><input type="hidden" name="leave_id" value="<?=(int)$leave['id']?>"><?php hr_select('Decision','decision',['approved'=>'Approve','rejected'=>'Reject']);hr_reason();?><button>Record decision</button></form><?php else:?><?=access_h($leave['review_reason'] ?? '')?><?php endif?></td></tr><?php endforeach?><?php if(!$snapshot['leaves']):?><tr><td colspan="4">No leave requests yet.</td></tr><?php endif?></tbody></table></div></section>
<section class="card"><h2>Request leave</h2><form method="post"><?php hr_fields('request_leave',$id,$version);?><div class="grid"><?php hr_select('Leave type','leave_type',['annual'=>'Annual leave','sick'=>'Sick leave','compassionate'=>'Compassionate leave','other'=>'Other']);hr_input('From','start_date','','date',true);hr_input('To','end_date','','date',true);?></div><?php hr_textarea('Reason','reason','',true,2000);?><button>Submit request</button></form></section>
